package org.sleepwell.app;
import android.content.Context;
/** All methods are called only by SonarNight's one ordered storage worker. */
final class SonarNightStore implements SonarNight.Sink {
 private final Context app;private final TrackingService.StoreFactory factory;private final SonarNight.Clock clock;private final AwakeRuntime awake;private final SonarClipPolicy clips;private Store store;private SonarNight.Session session;private boolean clockChanged,backupProduction;
 SonarNightStore(Context app,TrackingService.StoreFactory factory,SonarNight.Clock clock){this(app,factory,clock,null);}
 SonarNightStore(Context app,TrackingService.StoreFactory factory,SonarNight.Clock clock,AwakeRuntime awake){this(app,factory,clock,awake,SonarClipPolicy.OFF);}
 SonarNightStore(Context app,TrackingService.StoreFactory factory,SonarNight.Clock clock,AwakeRuntime awake,SonarClipPolicy clips){this.clips=java.util.Objects.requireNonNull(clips);this.app=app.getApplicationContext();this.factory=factory;this.clock=clock;this.awake=awake;}
 public SonarNight.Session begin(SonarConfig config,String capture)throws Exception{return begin(config,capture,false);}
 public SonarNight.Session begin(SonarConfig config,String capture,boolean analysis)throws Exception{store=factory.open(app);backupProduction=factory==TrackingService.PRODUCTION_STORE&&Records.factory==Records.PRODUCTION&&"sleepwell.db".equals(store.getDatabaseName());long beforeWall=clock.wall(),beforeElapsed=clock.millis();long id=store.begin(SensorProvenance.SONAR,SensorProvenance.sonar(config,capture),SoundAnalysisProvenance.encode(SoundAnalysisStatus.initial(analysis)));long wall=store.rows("SELECT start FROM sessions WHERE id=?",Long.toString(id)).get(0).getLong("start");long elapsed=Math.addExact(beforeElapsed,wall-beforeWall);if(elapsed<0||Math.abs((clock.millis()-beforeElapsed)-(clock.wall()-beforeWall))>2000){store.end(id,true,0,wall,SoundAnalysisProvenance.encode(analysis?new SoundAnalysisStatus(true,"error",0,"capture"):SoundAnalysisStatus.initial(false)));throw new IllegalStateException("The clock changed while starting. Start contactless tracking again.");}if(awake!=null)awake.begin(id,wall,elapsed,false);return session=new SonarNight.Session(id,wall,elapsed);}
 private void checkClock(){if(!clockChanged&&session!=null&&Math.abs(clock.wall()-(session.wall+clock.millis()-session.elapsed))>2000){store.clockChanged(session.id);clockChanged=true;}}
 public void periodicityBegin(long id,boolean enabled){EchoPeriods.begin(store,id,enabled);}
 public void periodicityWindow(long id,long from,long to,Double rate,double correlation,String quality){checkClock();EchoPeriods.append(store,id,from,to,rate,correlation,quality);}
 public void periodicityEnd(long id,boolean interrupted){EchoPeriods.end(store,id,interrupted);}
 public void checkpoint(long id,long from,long to,Double movement,String quality,int samples,long active){checkClock();store.sonarCheckpoint(id,from,to,movement,quality,samples,active);}
 public void pause(long id,long at){if(awake!=null)awake.pause();checkClock();store.pause(id,at);automationTransition(id,true);}
 public void resume(long id,long at){if(awake!=null)awake.resume();checkClock();store.resume(id,at);automationTransition(id,false);}
 private void automationTransition(long id,boolean paused){if(session==null||session.id!=id)return;try{java.util.List<org.json.JSONObject> rows=store.rows("SELECT id,start,end FROM tracking_pauses WHERE session=? ORDER BY id DESC LIMIT 1",""+id);if(rows.isEmpty())return;org.json.JSONObject row=rows.get(0);if(paused!=row.isNull("end"))return;Automations.confirmed(app,paused?AutomationEvent.Kind.TRACKING_PAUSED:AutomationEvent.Kind.TRACKING_RESUMED,id+":"+session.wall+":pause:"+row.optLong("id"));}catch(RuntimeException unavailable){Prefs.put(app,"automationEventError","A committed contactless transition could not be queued. Recording is unaffected.");}}
 public void end(long id,long at,long active,boolean interrupted){if(awake!=null)awake.finishAndWait(at,interrupted);checkClock();store.end(id,interrupted,active,at);backupEnded(id,at,interrupted);}
 public void soundEvent(long id,long at,long duration,String category,double score){checkClock();long event=store.soundEvent(id,at,duration,category,score,null);if(backupProduction)Automations.soundRecognized(app,id,event,at,category);}
 public void clip(long id,SonarSoundClips.Clip clip)throws Exception{checkClock();if(session==null||session.id!=id)throw new IllegalStateException("Sound clip owner changed");SonarClipWriter.save(app,store,id,clip,clips);}
 public void soundStatus(long id,SoundAnalysisStatus analysis){checkClock();store.soundAnalysisCheckpoint(id,SoundAnalysisProvenance.encode(analysis));}
 public void end(long id,long at,long active,boolean interrupted,SoundAnalysisStatus analysis){if(awake!=null)awake.finishAndWait(at,interrupted);checkClock();store.end(id,interrupted,active,at,SoundAnalysisProvenance.encode(analysis));backupEnded(id,at,interrupted);}
 private void backupEnded(long id,long at,boolean interrupted){if(!interrupted&&session!=null&&session.id==id){AutoCalendar.ended(app,id,session.wall,at,backupProduction);AutoCloudBackups.ended(app,id,session.wall,at,backupProduction);}}
 public void close(){if(store!=null){Store owned=store;store=null;owned.close();}}
}
